<?php if (!in_array($_SESSION['role'],['admin','pimpinan','bendahara'],true)){http_response_code(403);exit('Akses ditolak.');} ?><h1>Keuangan</h1><p><a href="?page=laporan">Laporan periode, saldo, dan unduh CSV</a></p><?php if(in_array($_SESSION['role'],['admin','bendahara'],true)): ?><section class="card"><h2>Tambah Transaksi</h2><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><div class="formgrid"><label>Tanggal<input type="date" name="tanggal" value="<?=date('Y-m-d')?>" required></label><label>Jenis<select name="jenis" id="jenis" onchange="categories()"><option value="masuk">Pemasukan</option><option value="keluar">Pengeluaran</option></select></label><label>Kategori<select name="kategori" id="kategori"></select></label><label>Nominal (Rp)<input type="number" name="nominal" min=".01" step=".01" required></label><label>Uraian<input name="uraian" maxlength="255" required></label></div><button name="action" value="add_keuangan">Simpan Transaksi</button></form></section><?php endif; ?><section class="card"><h2>200 Transaksi Terbaru</h2><p class="muted">Transaksi tidak dapat diubah atau dihapus. Kesalahan input dikoreksi dengan transaksi pembalik yang tercatat (siapa, kapan, dan alasannya).</p><div class="tablewrap"><table><thead><tr><th>No</th><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Uraian</th><th>Nominal</th><th>Status</th></tr></thead><tbody><?php $canWrite=in_array($_SESSION['role'],['admin','bendahara'],true); foreach(db()->query('SELECT t.id,t.tanggal,t.jenis,t.kategori,t.uraian,t.nominal,c1.id AS dikoreksi,c1.alasan AS alasan,c2.transaction_id AS pembalik_atas,c3.transaction_id AS pengganti_atas FROM transactions t LEFT JOIN transaction_corrections c1 ON c1.transaction_id=t.id LEFT JOIN transaction_corrections c2 ON c2.reversal_id=t.id LEFT JOIN transaction_corrections c3 ON c3.replacement_id=t.id ORDER BY t.tanggal DESC,t.id DESC LIMIT 200') as $r): ?><tr><td><?=esc($r['id'])?></td><td><?=esc($r['tanggal'])?></td><td><?=esc($r['jenis'])?></td><td><?=esc($r['kategori'])?></td><td><?=esc($r['uraian'])?></td><td><?=rupiah($r['nominal'])?></td><td><?php if($r['dikoreksi']!==null): ?>Dikoreksi<br><span class="muted"><?=esc($r['alasan'])?></span><?php elseif($r['pembalik_atas']!==null): ?>Pembalik atas #<?=esc($r['pembalik_atas'])?><?php elseif($canWrite): ?><details><summary>Koreksi</summary><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="id" value="<?=esc($r['id'])?>"><div class="formgrid"><label>Alasan koreksi<input name="alasan" maxlength="255" required></label><label>Tanggal koreksi<input type="date" name="tanggal_koreksi" value="<?=date('Y-m-d')?>" required></label></div><label><input type="checkbox" name="ganti" value="1"> Catat transaksi pengganti yang benar</label><div class="formgrid"><label>Tanggal<input type="date" name="tanggal" value="<?=esc($r['tanggal'])?>"></label><label>Jenis<select name="jenis"><option value="masuk"<?=$r['jenis']==='masuk'?' selected':''?>>Pemasukan</option><option value="keluar"<?=$r['jenis']==='keluar'?' selected':''?>>Pengeluaran</option></select></label><label>Kategori (sesuai jenis)<select name="kategori"><optgroup label="Pemasukan"><?php foreach(categories('masuk') as $k): ?><option value="<?=esc($k)?>"><?=esc(str_replace('_',' ',$k))?></option><?php endforeach; ?></optgroup><optgroup label="Pengeluaran"><?php foreach(categories('keluar') as $k): ?><option value="<?=esc($k)?>"><?=esc(str_replace('_',' ',$k))?></option><?php endforeach; ?></optgroup></select></label><label>Nominal (Rp)<input type="number" name="nominal" min=".01" step=".01" value="<?=esc($r['nominal'])?>"></label><label>Uraian<input name="uraian" maxlength="255" value="<?=esc($r['uraian'])?>"></label></div><button name="action" value="koreksi_keuangan">Simpan Koreksi</button></form></details><?php endif; ?><?php if($r['pengganti_atas']!==null): ?><span class="muted">Pengganti #<?=esc($r['pengganti_atas'])?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><script>function categories(){const type=document.getElementById('jenis').value;const values=type==='masuk'?['infaq','usaha','iuran','donasi','lainnya']:['operasional','listrik_air','konsumsi','pendidikan','pemeliharaan','lainnya'];document.getElementById('kategori').replaceChildren(...values.map(x=>new Option(x.replaceAll('_',' '),x)));}if(document.getElementById('jenis'))categories();</script>
